// ValidateCertificateSHA256Options rejects combinations that could bypass leaf pins.
func ValidateCertificateSHA256Options(options option.OutboundTLSOptions) error {
	if len(options.CertificateSHA256) == 0 {
		return nil
	}
	if !options.Enabled || options.Insecure || len(options.CertificatePublicKeySHA256) > 0 || len(options.Certificate) > 0 || options.CertificatePath != "" {
		return E.New("certificate_sha256 conflicts with disabled TLS, insecure, public-key pin or certificate authority")
	}
	if (options.Engine != "" && options.Engine != C.TLSEngineGo) || (options.Reality != nil && options.Reality.Enabled) || (options.ECH != nil && options.ECH.Enabled) {
		return E.New("certificate_sha256 requires plain Go or uTLS without Reality or ECH")
	}
	for _, pin := range options.CertificateSHA256 {
		if len(pin) != sha256.Size {
			return E.New("invalid certificate_sha256 length")
		}
	}
	return nil
}

// VerifyCertificateSHA256 authenticates only the leaf certificate's complete DER.
func VerifyCertificateSHA256(knownHashValues [][]byte, rawCerts [][]byte) error {
	if len(rawCerts) == 0 {
		return E.New("missing peer certificate")
	}
	hashValue := sha256.Sum256(rawCerts[0])
	matched := 0
	for _, value := range knownHashValues {
		matched |= subtle.ConstantTimeCompare(value, hashValue[:])
	}
	if matched != 1 {
		return E.New("unrecognized remote leaf certificate")
	}
	return nil
}

